#!/usr/bin/env python3import argparseimport csvimport mathimport sysfrom pathlib import Pathimport torchimport torch.nn.functional as FROOT_DIR = Path(__file__).resolve().parents[1]if str(ROOT_DIR) not in sys.path:    sys.path.insert(0, str(ROOT_DIR))from analysis.recompute_transfer_metrics import (  # noqa: E402    build_dataset,    build_loader,    build_model,    compute_source_fisher_ratio,    get_task_classes,    load_checkpoint,)DEFAULT_CONFIGS = {    "plain",    "raw_global_w1",    "trainable_s003_reg000",    "trainable_s003_raw_global_w1",}JOB_FIELDS = [    "task",    "source_dataset",    "target_dataset",    "seed",    "config",    "reshaper",    "strength",    "trainable",    "init_seed",    "reg_trade_off",    "dual_relation",    "intra",    "structure_target",    "detach_features",    "est_weight",]def read_tsv(path):    with Path(path).open("r", encoding="utf-8", newline="") as handle:        return list(csv.DictReader(handle, delimiter="\t"))def read_jobs_tsv(path):    rows = []    with Path(path).open("r", encoding="utf-8", newline="") as handle:        reader = csv.reader(handle, delimiter="\t")        for parts in reader:            if not parts:                continue            if parts[0] == "task":                continue            row = {field: parts[idx] if idx < len(parts) else "" for idx, field in enumerate(JOB_FIELDS)}            rows.append(row)    return rowsdef write_tsv(path, rows, fields):    path = Path(path)    path.parent.mkdir(parents=True, exist_ok=True)    with path.open("w", encoding="utf-8", newline="\n") as handle:        writer = csv.DictWriter(handle, delimiter="\t", fieldnames=fields)        writer.writeheader()        for row in rows:            writer.writerow({field: format_value(row.get(field)) for field in fields})def format_value(value):    if value is None:        return ""    if isinstance(value, float):        if math.isnan(value) or math.isinf(value):            return ""        return f"{value:.8f}"    return str(value)def parse_csv_set(text):    if text is None or str(text).strip() == "":        return None    return {part.strip() for part in str(text).split(",") if part.strip()}def source_model_name(row):    source_tile = row["source_dataset"].split("/")[1]    tag = f"v243b_cf_{row['task']}_seed{row['seed']}_{row['config']}"    return f"pseltae_{source_tile}_closedset_noshift_sourcephasecompact_p5_{tag}"def load_model_for_row(row, args, device):    experiment = source_model_name(row)    checkpoint_path = Path(args.outputs_root) / experiment / "fold_0" / "model.pt"    if not checkpoint_path.exists():        return None, [], checkpoint_path    classes = get_task_classes(args.data_root, row["source_dataset"], closed_set=True)    model = build_model(args.model, len(classes), args.with_extra, device)    load_checkpoint(model, checkpoint_path, device)    return model, classes, checkpoint_path@torch.no_grad()def collect_features_and_logits(model, loader, device, max_batches):    features = []    labels = []    entropies = []    confidences = []    correct = 0    total = 0    for batch_idx, sample in enumerate(loader):        if max_batches > 0 and batch_idx >= max_batches:            break        pixels = sample["pixels"].to(device=device, non_blocking=True)        mask = sample["valid_pixels"].to(device=device, non_blocking=True)        positions = sample["positions"].to(device=device, non_blocking=True)        extra = sample["extra"].to(device=device, non_blocking=True)        y = sample["label"].to(device=device, non_blocking=True)        logits, feats = model.forward(pixels, mask, positions, extra, return_feats=True)        probs = F.softmax(logits, dim=1)        entropy = -(probs * probs.clamp_min(1e-12).log()).sum(dim=1)        confidence, pred = probs.max(dim=1)        features.append(feats.detach().cpu())        labels.append(y.detach().cpu())        entropies.append(entropy.detach().cpu())        confidences.append(confidence.detach().cpu())        correct += int((pred == y).sum().item())        total += int(y.numel())    if not features:        return None    return {        "features": torch.cat(features, dim=0).float(),        "labels": torch.cat(labels, dim=0).long(),        "entropy": torch.cat(entropies, dim=0).float(),        "confidence": torch.cat(confidences, dim=0).float(),        "accuracy": correct / max(total, 1),        "count": total,    }def effective_rank(features, eps=1e-12):    if features is None or features.shape[0] < 2:        return float("nan")    centered = features - features.mean(dim=0, keepdim=True)    cov = centered.t().matmul(centered) / max(features.shape[0] - 1, 1)    eigvals = torch.linalg.eigvalsh(cov).clamp_min(0.0)    total = eigvals.sum()    if total <= eps:        return 0.0    probs = eigvals / total    entropy = -(probs * probs.clamp_min(eps).log()).sum()    return float(torch.exp(entropy).item())def safe_float(value):    if value is None:        return None    text = str(value).strip()    if text == "":        return None    try:        return float(text)    except ValueError:        return Nonedef pearson(xs, ys):    pairs = [(x, y) for x, y in zip(xs, ys) if x is not None and y is not None]    if len(pairs) < 3:        return None, len(pairs)    x = torch.tensor([p[0] for p in pairs], dtype=torch.float64)    y = torch.tensor([p[1] for p in pairs], dtype=torch.float64)    x = x - x.mean()    y = y - y.mean()    denom = torch.sqrt((x.pow(2).sum() * y.pow(2).sum()).clamp_min(1e-24))    return float((x * y).sum().item() / denom.item()), len(pairs)def filter_jobs(rows, args):    tasks = parse_csv_set(args.tasks)    seeds = parse_csv_set(args.seeds)    configs = parse_csv_set(args.configs) or DEFAULT_CONFIGS    out = []    seen = set()    for row in rows:        if tasks is not None and row["task"] not in tasks:            continue        if seeds is not None and row["seed"] not in seeds:            continue        if row["config"] not in configs:            continue        key = (row["task"], row["seed"], row["config"])        if key in seen:            continue        seen.add(key)        out.append(row)    return outdef extract(args):    device = torch.device(args.device)    jobs = filter_jobs(read_jobs_tsv(args.jobs_tsv), args)    rows = []    for idx, job in enumerate(jobs, start=1):        print(            f"[{idx}/{len(jobs)}] task={job['task']} seed={job['seed']} config={job['config']}",            flush=True,        )        model, classes, checkpoint_path = load_model_for_row(job, args, device)        base = {            "task": job["task"],            "seed": job["seed"],            "config": job["config"],            "source_dataset": job["source_dataset"],            "target_dataset": job["target_dataset"],            "checkpoint": str(checkpoint_path),            "status": "ok",        }        if model is None:            base["status"] = "missing_checkpoint"            rows.append(base)            continue        source_ds = build_dataset(args.data_root, job["source_dataset"], classes, True, args.with_extra)        target_ds = build_dataset(args.data_root, job["target_dataset"], classes, True, args.with_extra)        source_loader = build_loader(source_ds, args.batch_size, args.num_workers)        target_loader = build_loader(target_ds, args.batch_size, args.num_workers)        source = collect_features_and_logits(model, source_loader, device, args.max_batches)        target = collect_features_and_logits(model, target_loader, device, args.max_batches)        if source is None or target is None:            base["status"] = "empty_loader"            rows.append(base)            continue        source_fisher = compute_source_fisher_ratio(source["features"], source["labels"])        base.update(            {                "source_count": source["count"],                "target_count": target["count"],                "source_accuracy": source["accuracy"],                "target_accuracy": target["accuracy"],                "source_fisher": source_fisher,                "source_effrank": effective_rank(source["features"]),                "target_entropy": float(target["entropy"].mean().item()),                "target_confidence": float(target["confidence"].mean().item()),                "target_effrank": effective_rank(target["features"]),            }        )        rows.append(base)    fields = [        "task",        "seed",        "config",        "source_dataset",        "target_dataset",        "checkpoint",        "status",        "source_count",        "target_count",        "source_accuracy",        "target_accuracy",        "source_fisher",        "source_effrank",        "target_entropy",        "target_confidence",        "target_effrank",    ]    write_tsv(args.output_tsv, rows, fields)def metric_row_map(rows):    return {        (row["task"], row["seed"], row["config"]): row        for row in rows        if row.get("status") == "ok"    }def delta(metric_rows, task, seed, config, plain, field):    left = metric_rows.get((task, seed, config))    right = metric_rows.get((task, seed, plain))    if left is None or right is None:        return None    lv = safe_float(left.get(field))    rv = safe_float(right.get(field))    if lv is None or rv is None:        return None    return lv - rvdef merge(args):    metric_files = sorted(Path(args.metric_dir).glob(args.metric_glob))    metric_rows = []    for path in metric_files:        metric_rows.extend(read_tsv(path))    metric_rows = [row for row in metric_rows if row.get("task")]    metric_map = metric_row_map(metric_rows)    contrasts = read_tsv(args.contrast_tsv)    metric_fields = ["source_fisher", "source_effrank", "target_entropy", "target_confidence", "target_effrank"]    joined = []    for row in contrasts:        task = row["task"]        seed = row["seed"]        out = dict(row)        for field in metric_fields:            out[f"raw_delta_{field}"] = delta(metric_map, task, seed, "raw_global_w1", "plain", field)            out[f"reshaper_delta_{field}"] = delta(                metric_map, task, seed, "trainable_s003_reg000", "plain", field            )            out[f"combo_delta_{field}"] = delta(                metric_map, task, seed, "trainable_s003_raw_global_w1", "plain", field            )        joined.append(out)    effect_specs = [        ("raw_grad_effect", "raw_delta_"),        ("reshaper_direct_effect", "reshaper_delta_"),        ("reshaper_combo_total_effect", "combo_delta_"),        ("interaction_like", "combo_delta_"),    ]    corr_rows = []    for effect_field, prefix in effect_specs:        effects = [safe_float(row.get(effect_field)) for row in joined]        for metric in metric_fields:            metric_field = f"{prefix}{metric}"            metrics = [safe_float(row.get(metric_field)) for row in joined]            corr, n = pearson(metrics, effects)            corr_rows.append(                {                    "effect": effect_field,                    "metric_delta": metric_field,                    "pearson": corr,                    "n": n,                    "r2": None if corr is None else corr * corr,                }            )    output_dir = Path(args.output_dir)    joined_fields = list(joined[0].keys()) if joined else []    write_tsv(output_dir / "geometry_effect_join.tsv", joined, joined_fields)    write_tsv(output_dir / "geometry_effect_correlations.tsv", corr_rows, ["effect", "metric_delta", "pearson", "r2", "n"])    write_tsv(        output_dir / "geometry_metrics.tsv",        metric_rows,        [            "task",            "seed",            "config",            "source_dataset",            "target_dataset",            "checkpoint",            "status",            "source_count",            "target_count",            "source_accuracy",            "target_accuracy",            "source_fisher",            "source_effrank",            "target_entropy",            "target_confidence",            "target_effrank",        ],    )def parse_args():    parser = argparse.ArgumentParser(description="v2.4.3b representation geometry diagnostic.")    sub = parser.add_subparsers(dest="mode", required=True)    extract_parser = sub.add_parser("extract")    extract_parser.add_argument("--jobs_tsv", required=True)    extract_parser.add_argument("--output_tsv", required=True)    extract_parser.add_argument("--data_root", default="/data/user/DBL/timematch_data")    extract_parser.add_argument("--outputs_root", default="outputs")    extract_parser.add_argument("--tasks", default="")    extract_parser.add_argument("--seeds", default="")    extract_parser.add_argument(        "--configs",        default="plain,raw_global_w1,trainable_s003_reg000,trainable_s003_raw_global_w1",    )    extract_parser.add_argument("--device", default="cuda")    extract_parser.add_argument("--batch_size", type=int, default=128)    extract_parser.add_argument("--num_workers", type=int, default=8)    extract_parser.add_argument("--max_batches", type=int, default=64)    extract_parser.add_argument("--model", default="pseltae", choices=["pseltae", "psetae", "psetcnn", "psegru"])    extract_parser.add_argument("--with_extra", action="store_true")    merge_parser = sub.add_parser("merge")    merge_parser.add_argument("--metric_dir", required=True)    merge_parser.add_argument("--metric_glob", default="geometry_rows_gpu*.tsv")    merge_parser.add_argument("--contrast_tsv", required=True)    merge_parser.add_argument("--output_dir", required=True)    return parser.parse_args()def main():    args = parse_args()    if args.mode == "extract":        extract(args)    elif args.mode == "merge":        merge(args)    else:        raise ValueError(args.mode)if __name__ == "__main__":    main()